// The coverage report (PLAN.md §3, §12 — Session 9): what each of the book's
// exercises became — mirrored by a drill set of our own, generated by the
// verb engine, or skipped with its reason — chapter by chapter, with the
// lesson that teaches it. No book text: the blueprint's numbers, types and
// headings, and our own set titles.
//   node coverage.mjs            the summary, chapter by chapter
//   node coverage.mjs --write    also writes COVERAGE.md next to this file
//   node coverage.mjs --strict   exit 1 unless every exercise is covered
import fs from "node:fs";
import path from "node:path";
import { loadCourse, ROOT } from "./load.mjs";

const C = loadCourse(), { CX } = C;
const B = JSON.parse(fs.readFileSync(path.join(ROOT, "tools/book/blueprint.json"), "utf8"));
const order = ch => ch.startsWith("app") ? 100 + ch.charCodeAt(3) : +ch.slice(1);
const chapters = Object.keys(B).filter(ch => B[ch].exercises.length).sort((a, b) => order(a) - order(b));
const lessonOf = set => { const s = set && CX.byId[set.sec]; return s ? s : null; };
const stageSign = s => (CX.stages.find(x => x.id === s.stage) || {}).sign || "";

const rows = [], tally = { mirrored: 0, generated: 0, skipped: 0, planned: 0, none: 0 };
chapters.forEach(ch => B[ch].exercises.forEach(e => {
  const c = C.cxCovOf(e.id), set = c.set ? CX.sets[c.set] : null, sec = lessonOf(set) || (c.sec ? CX.byId[c.sec] : null);
  tally[c.st] = (tally[c.st] || 0) + 1;
  rows.push({ ch, e, c, set, sec, items: set ? (set.gen ? `${set.n || 10} generated` : (set.items || []).length) : "" });
}));
const total = rows.length, covered = tally.mirrored + tally.generated + tally.skipped;

console.log(`\nThe book's exercises: ${total} · covered ${covered} (${Math.round(covered / total * 1000) / 10} %) — mirrored ${tally.mirrored} · generated ${tally.generated} · skipped ${tally.skipped}${tally.planned ? ` · planned ${tally.planned}` : ""}${tally.none ? ` · none ${tally.none}` : ""}\n`);
chapters.forEach(ch => {
  const r = rows.filter(x => x.ch === ch), n = r.filter(x => ["mirrored", "generated", "skipped"].includes(x.c.st)).length;
  console.log(`${ch.padEnd(4)} ${String(n).padStart(2)}/${String(r.length).padEnd(2)} ${n === r.length ? "✓" : "…"} ${CX.chapters[ch] || ""}`);
});

if (process.argv.includes("--write")) {
  const md = [
    "# Coverage — the book's exercises and what they became",
    "",
    "Generated by `node tools/course/coverage.mjs --write` from `tools/book/blueprint.json` and the course packs (`js/course/`).",
    "Every exercise of *Practice Makes Perfect: Complete German Grammar* is **mirrored** (a drill set of our own sentences, 8+ items,",
    "same exercise type), **generated** (a table the verb engine makes) or **skipped** (with the reason). No book text is kept here:",
    "only the blueprint's numbers, types and item counts, and our own set titles.",
    "",
    `**${covered} of ${total} covered (${Math.round(covered / total * 1000) / 10} %)** — mirrored ${tally.mirrored} · generated ${tally.generated} · skipped ${tally.skipped}${tally.planned ? ` · planned ${tally.planned}` : ""}${tally.none ? ` · none ${tally.none}` : ""}.`,
    "",
    "| Chapter | Exercises | Covered |",
    "|---|---:|---:|",
    ...chapters.map(ch => { const r = rows.filter(x => x.ch === ch), n = r.filter(x => ["mirrored", "generated", "skipped"].includes(x.c.st)).length; return `| ${ch.replace(/^c/, "")} · ${CX.chapters[ch] || ""} | ${r.length} | ${n === r.length ? "✓ " : ""}${n} |`; }),
    "",
  ];
  chapters.forEach(ch => {
    md.push(`## ${ch.replace(/^c/, "Chapter ")} · ${CX.chapters[ch] || ""}`, "", "| Übung | Type · items | Status | Our drill set | Lesson |", "|---|---|---|---|---|");
    rows.filter(x => x.ch === ch).forEach(({ e, c, set, sec, items }) => {
      const st = c.st === "mirrored" ? "mirrored" : c.st === "generated" ? "generated" : c.st === "skipped" ? `skipped — ${c.why || ""}` : c.st;
      const drill = set ? `\`${set.id}\` ${set.title}${set.ex !== e.id ? ` (with ${set.ex})` : ""} · ${items}` : "—";
      const lesson = sec ? `${stageSign(sec)} · ${sec.title}` : "—";
      md.push(`| ${e.id} | ${e.type} · ${e.items} | ${st} | ${drill.replace(/\|/g, "/")} | ${lesson.replace(/\|/g, "/")} |`);
    });
    md.push("");
  });
  fs.writeFileSync(path.join(ROOT, "tools/course/COVERAGE.md"), md.join("\n"));
  console.log(`\nwritten: tools/course/COVERAGE.md`);
}
if (process.argv.includes("--strict") && covered !== total) process.exit(1);
